// Durations available for the current model selection. A SINGLE selected model
// shows all of its own durations; MULTIPLE selected models show only the values
// common to all of them (intersection), so a generation request can't ask for a
// duration one of the providers rejects. Order follows the first model's list.
export function getDurationOptions(selectedValues: string[]): string[] {
  const lists = selectedValues
    .map((v) => videoModelOptions.find((m) => m.value === v)?.durations)
    .filter((d): d is string[] => Array.isArray(d))
  if (lists.length === 0) return []
  return lists.reduce((acc, list) => acc.filter((d) => list.includes(d)))
}

// Resolutions available for the current model selection — same rule as
// durations: single model shows all of its resolutions, multiple show only the
// values common to all (e.g. Seedance is 480p/720p, so it can't send 1080p).
export function getResolutionOptions(selectedValues: string[]): string[] {
  const lists = selectedValues
    .map((v) => videoModelOptions.find((m) => m.value === v)?.resolutions)
    .filter((r): r is string[] => Array.isArray(r))
  if (lists.length === 0) return []
  return lists.reduce((acc, list) => acc.filter((r) => list.includes(r)))
}

// Aspect ratios available for the current selection — single model shows all of
// its ratios, multiple show only the values common to all (e.g. only Seedance
// offers 3:4).
export function getAspectRatioOptions(selectedValues: string[]): string[] {
  const lists = selectedValues
    .map((v) => videoModelOptions.find((m) => m.value === v)?.aspectRatios)
    .filter((a): a is string[] => Array.isArray(a))
  if (lists.length === 0) return []
  return lists.reduce((acc, list) => acc.filter((a) => list.includes(a)))
}





// `pltt dev` serves the simulator on localhost — the CLI bundler hardcodes
// NODE_ENV="production" for palette-app frameworks, so we detect the dev
// host at runtime instead of trusting the build-time flag.
const isDevHost =
  typeof window !== "undefined" &&
  /^(localhost|127\.0\.0\.1|0\.0\.0\.0)$/.test(window.location.hostname)

const devModels = isDevHost
  ? [
    {
      label: "Flux",
      value: "flux_schnell",
      description: "Fast processing with incredible sharp detail",
      version: "Schnell",
      icon: FluxColorfulIcon,
      color: "#F97316",
      options: ["HD", "Text to Image", "Image to Image"],
      reference: false,
    },
  ]
  : []

